18	
19	import java.util.List;
20	
21	/**
22	 * Thrown when a request supplies one or more fields whose value is present but
23	 * fails a business rule (for example a telephone that does not normalize to
24	 * exactly ten digits).
25	 * <p>
26	 * Carries the names of the offending fields so the {@link ExceptionControllerAdvice}
27	 * can surface them to the client under the {@code errors} property of a
28	 * {@code 400 Bad Request} response.
29	 */
30	public class InvalidFieldsException extends RuntimeException {
31	
32	    private final List<String> fields;
33	
34	    public InvalidFieldsException(List<String> fields) {
35	        super("Invalid field values: " + fields);
36	        this.fields = List.copyOf(fields);
